<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage45Api,Context,Eligibility,AfterSale,Page,Evaluation} from '../../../business-common/stage45/types'
import {label,money} from '../../../business-common/stage45/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
const props=defineProps<{api:Stage45Api;orderId:string;merchant?:boolean;refreshKey?:number}>()
const context=ref<Context|null>(null),eligible=ref<Eligibility|null>(null),sales=ref<AfterSale[]>([]),evaluations=ref<Evaluation[]>([]),error=ref(''),loading=ref(false)
let ticket=0
async function load(){if(!props.orderId)return;const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{const ctx=await props.api.read<Context>('/context');const results=await Promise.all([ctx.permissions.includes('aftersale.read')?props.api.read<Page<AfterSale>>('/aftersales',{orderId:props.orderId,pageSize:50}):null,!props.merchant?props.api.read<Eligibility>('/orders/'+props.orderId+'/eligibility'):null,!props.merchant?props.api.read<Page<Evaluation>>('/evaluations',{orderId:props.orderId,pageSize:50}):null]);if(run===ticket&&owner===props.api.owner()){context.value=ctx;sales.value=results[0]?.records||[];eligible.value=results[1];evaluations.value=results[2]?.records||[]}}catch(e){if(run===ticket){context.value=null;sales.value=[];eligible.value=null;evaluations.value=[];error.value=e instanceof Error?e.message:'售后与评价入口读取失败。'}}finally{if(run===ticket)loading.value=false}}
function open(url:string){uni.navigateTo({url})}
watch(()=>[props.orderId,props.api.owner()],()=>{ticket++;context.value=null;sales.value=[];eligible.value=null;evaluations.value=[];load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;sales.value=[];evaluations.value=[]})
</script>
<template><view class="s45 order-actions"><BaseCard v-if="error"><text class="error">{{error}}</text><AppButton class="s45-action" variant="secondary" @click="load">重新读取售后与评价</AppButton></BaseCard><text v-if="loading" class="muted">正在核对售后与评价资格…</text><BaseCard v-if="eligible"><text class="section">售后与商品评价</text><view v-for="item in eligible.items" :key="item.orderItemId" class="group"><text class="strong">{{item.name}}</text><text class="muted">可售后 {{item.availableQuantity}} 件 · 按原商品实付核定</text><view class="buttons"><AppButton class="s45-action" v-if="eligible.eligible&&item.availableQuantity" variant="secondary" size="compact" @click="open('/pages/after-sale/apply/index?orderId='+orderId+'&itemId='+item.orderItemId)">申请售后</AppButton><AppButton class="s45-action" v-if="item.canEvaluate&&!item.evaluated" variant="secondary" size="compact" @click="open('/pages/evaluation/index?orderId='+orderId+'&itemId='+item.orderItemId)">评价商品</AppButton></view></view><text class="muted">完成后退款保留评价资格。每个有效完成商品项可评价一次。</text></BaseCard><BaseCard v-if="sales.length"><text class="section">本订单售后记录</text><view v-for="row in sales" :key="row.id" class="group"><text>{{row.goodsName}} · {{row.quantity}} 件 · ¥{{money(row.amountCent)}}</text><text class="muted">{{label(row.state)}} · 资金 {{label(row.fundingState)}}</text><AppButton class="s45-action" variant="secondary" size="compact" @click="open('/pages/after-sale/detail/index?id='+row.id)">查看售后</AppButton></view></BaseCard><BaseCard v-if="evaluations.length"><text class="section">已提交评价</text><view v-for="row in evaluations" :key="row.id" class="group"><text>{{row.goodsName}} · {{row.star==null?'历史无单星':row.star+' 星'}}</text><AppButton class="s45-action" variant="secondary" size="compact" @click="open('/pages/evaluation/index?id='+row.id)">回看原评价</AppButton></view></BaseCard><BaseCard v-if="merchant&&context?.permissions.includes('funds.read')"><text class="section">本订单资金</text><text class="muted">查看付款、退款、分账及回退的当前事实。</text><AppButton class="s45-action" variant="secondary" @click="open('/pages/funds/detail/index?id='+orderId)">查看资金详情</AppButton></BaseCard></view></template>
<style scoped lang="scss">@import './stage45.scss';.order-actions{margin-top:16px}.group{display:flex;flex-direction:column;gap:8px;border-bottom:1px solid $color-border;padding:12px 0}</style>
